using System;
using System.Linq;
using System.Reflection;
using UnityEditor;
using UnityEngine;
namespace BWVR.Editor {
public static class ProvisionChecks {
 static void Require(bool ok,string reason){if(!ok)throw new Exception(reason);}
 [MenuItem("BWVR/Verify resource gifts and religion model")]
 public static void VerifyModel(){var s=new ResourceState{wood=0,wheat=0};Require(s.ReceiveProvision(VillageResource.Wheat,3,0)==3&&s.wheat==3&&s.giftedFood==3,"Food gift accounting incorrect");Require(s.ReceiveProvision(VillageResource.Wood,2,0)==0,"Gift cooldown did not stop duplicate receipt");Require(s.ReceiveProvision(VillageResource.Wood,2,2)==2&&s.wood==2&&s.giftedWood==2,"Wood gift accounting incorrect");s.wood=s.Limit(VillageResource.Wood)-1;Require(s.ReceiveProvision(VillageResource.Wood,2,4)==1&&s.wood==s.Limit(VillageResource.Wood),"Gift overflowed storage");Require(s.ReceiveProvision(VillageResource.Wood,2,6)==0&&s.ReceiveProvision(VillageResource.Resin,2,6)==0&&s.ReceiveProvision(VillageResource.Wheat,float.NaN,6)==0,"Invalid/full gift applied");
  var m=new SocialMemory();float faith=m.faith;Require(m.WitnessProvision(0,1)&&Mathf.Abs(m.faith-faith-.04f)<.001f&&!m.WitnessProvision(2,1),"Faith receipt/cooldown failed");Require(m.WitnessProvision(5,.5f)&&Mathf.Abs(m.faith-faith-.06f)<.001f&&m.provisionsWitnessed==2,"Proportional witness credit failed");Require(!m.WitnessProvision(float.NaN,1)&&!m.WitnessProvision(10,float.NaN),"Nonfinite religious memory accepted");var copy=JsonUtility.FromJson<ResourceState>(JsonUtility.ToJson(s));var memory=JsonUtility.FromJson<SocialMemory>(JsonUtility.ToJson(m));Require(copy.Valid()&&memory.Valid()&&copy.giftedFood==3&&memory.provisionsWitnessed==2,"Gift/religion save invalid");copy.giftedFood=-1;Require(!copy.Valid(),"Invalid provision ledger accepted");Require(JsonUtility.FromJson<SocialMemory>("{}").Valid(),"Historical social memory invalid");Debug.Log("BWVR_PROVISION_MODEL_PASS: finite stock/capacity, receipt cooldown, proportional bounded faith, save/legacy and finite-input validation");}
 [MenuItem("BWVR/Verify held god actions and witnessed gifts (Play mode)")]
 public static void VerifyRuntime(){Require(EditorApplication.isPlaying,"Enter Play mode");var palette=UnityEngine.Object.FindAnyObjectByType<GodToolPalette>();var slice=palette.GetComponentInParent<QuestSlice>();var god=slice.GetComponentInChildren<CreatureHybrid>();var world=slice.GetComponentInChildren<VillageResources>();var nav=world.Navigation;var miracles=slice.GetComponentInChildren<DivineIntervention>();var actors=world.Gatherers.Select(a=>a.GetComponent<VillagerSocial>()).ToArray();var positions=actors.Select(a=>a.transform.position).ToArray();var rotations=actors.Select(a=>a.transform.rotation).ToArray();var flags=BindingFlags.Instance|BindingFlags.NonPublic;var field=typeof(QuestSlice).GetField("state",flags);var original=(SliceState)field.GetValue(slice);god.Interrupt("Provision QA");var test=new SliceState{developmentFocus=true,observeWithoutFoodWork=true};field.SetValue(slice,test);world.ResetWorld();test.Resources.wheat=test.Resources.wood=0;bool unlimited=miracles.tuning.unlimitedEnergy;miracles.tuning.unlimitedEnergy=true;GameObject wall=null;
  try{var point=world.StoreApproach;Require(world.CanReceiveProvision(point,VillageResource.Wheat,out _),"No safe gift point at stores");for(int i=0;i<actors.Length;i++){actors[i].ResetTask();actors[i].GetComponent<VillagerExploration>().ResetTask();actors[i].GetComponent<VillagerBlockPlay>().ResetTask();actors[i].transform.position=point+Vector3.back*nav.Scale*(100+i*5);}
   actors[0].transform.position=point+Vector3.back*nav.Scale*8;actors[0].transform.rotation=Quaternion.LookRotation(Vector3.forward);actors[1].transform.position=point+Vector3.forward*nav.Scale*8;actors[1].transform.rotation=Quaternion.LookRotation(Vector3.forward);actors[2].transform.position=point+Vector3.left*nav.Scale*10;actors[2].transform.rotation=Quaternion.LookRotation(Vector3.right);
   wall=new GameObject("Temporary gift sight blocker",typeof(BoxCollider));wall.transform.position=point+new Vector3(-5,2,0)*nav.Scale;wall.transform.localScale=new Vector3(1,6,4)*nav.Scale;Physics.SyncTransforms();Require(world.ProvisionVisible(actors[0],point)&&!world.ProvisionVisible(actors[1],point)&&!world.ProvisionVisible(actors[2],point),"Witness facing/range/occlusion setup failed");float seen=actors[0].Memory.faith,away=actors[1].Memory.faith,blocked=actors[2].Memory.faith;
   string before=JsonUtility.ToJson(test);Require(palette.Brush.CanGift(point,true,out _)&&before==JsonUtility.ToJson(test),"Gift preview mutated state");Require(palette.Brush.GiftPulse(point,true)&&test.Resources.wheat==3&&palette.Brush.LastGiftWitnesses==1&&actors[0].Memory.faith>seen&&actors[1].Memory.faith==away&&actors[2].Memory.faith==blocked,"Gift credited invisible witnesses or failed supply");seen=actors[0].Memory.faith;Require(!palette.Brush.GiftPulse(point,true)&&test.Resources.giftedFood==3,"Duplicate gift credited");test.Hybrid.time+=2;Require(palette.Brush.GiftPulse(point,false)&&test.Resources.wood==2&&actors[0].Memory.faith==seen,"Faith cooldown or timber gift failed");test.Hybrid.time+=4;Require(palette.Brush.GiftPulse(point,true)&&actors[0].Memory.faith>seen,"Later witnessed gift did not strengthen religion");
   var copy=JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(test));Require(copy.Valid()&&copy.Resources.giftedWood==2&&copy.Social(0).provisionsWitnessed==2&&copy.Hybrid.Evidence.events.Last().actor=="player"&&copy.Hybrid.Evidence.playerMiracles==0&&copy.Hybrid.Evidence.completedCreatureActions==0,"Saved gifts/faith or attribution invalid");test.Hybrid.time+=2;test.Resources.wheat=test.Resources.Limit(VillageResource.Wheat);before=JsonUtility.ToJson(test);Require(!palette.Brush.GiftPulse(point,true)&&before==JsonUtility.ToJson(test),"Full stores generated a paid religious event");test.Resources.wheat=0;test.paused=true;Require(!palette.Brush.GiftPulse(point,true),"Paused provision applied");test.paused=false;miracles.Suspended=true;Require(!palette.Brush.GiftPulse(point,true),"Suspended provision applied");miracles.Suspended=false;Require(!palette.Brush.CanGift(new Vector3(float.NaN,0,0),true,out _),"Nonfinite gift accepted");
   palette.Cancel();var ray=new Ray(point+Vector3.up*nav.Scale*20,Vector3.down);palette.Select(SpiritualTool.FoodGift);float gifted=test.Resources.giftedFood;palette.Process(ray,true,true,false,.02f,false);Require(test.Resources.giftedFood==gifted,"Selection held gesture replayed gift");palette.Process(ray,false,true,false,.02f,false);palette.Process(ray,true,true,false,.02f,false);Require(test.Resources.giftedFood>gifted,"Held food tool did not act at pointer");gifted=test.Resources.giftedFood;for(int i=0;i<10;i++)palette.Process(ray,true,true,false,.02f,false);Require(test.Resources.giftedFood==gifted,"Same-tick hold spammed gift");test.Hybrid.time+=2.1f;palette.Process(ray,true,true,false,.02f,false);Require(test.Resources.giftedFood>gifted,"Sustained hold did not give next bounded gift");palette.Process(ray,false,true,false,.02f,false);gifted=test.Resources.giftedFood;test.Hybrid.time+=3;palette.Process(ray,false,true,false,.02f,false);Require(test.Resources.giftedFood==gifted&&!palette.Sign.activeSelf&&!test.Hybrid.guidance.playerSign,"Released gift continued or placed a sign");
   var weather=slice.GetComponentInChildren<IslandWeather>();var target=weather.Targets.First(t=>t.kind=="tree"&&t.gameObject.activeInHierarchy&&t.GetComponent<CarryItem>()?.held!=true);var at=nav.Terrain.Project(target.transform.position);var material=test.Weather.Touch(target.id);material.wetness=0;material.heat=.4f;material.burning=true;ray=new Ray(at+Vector3.up*nav.Scale*20,Vector3.down);palette.Select(SpiritualTool.Rain);palette.Process(ray,false,true,false,.02f,false);float water=test.water,crops=test.crops;palette.Process(ray,true,true,false,.02f,false);Require(material.wetness>0&&material.heat<.4f&&test.water==water&&test.crops==crops&&!palette.Sign.activeSelf,"Rain failed local hold semantics or placed a sign");palette.Process(ray,false,true,false,.02f,false);Require(!palette.Brush.Active,"Rain continued after release");
   Debug.Log("BWVR_PROVISION_RUNTIME_PASS: line-of-sight/facing witnesses only, exact gifts, stored religious memory, cooldown/capacity/pause/suspend, pointer hold cadence/release, no new signs, local rain effects and player provenance");
  }finally{if(wall!=null)UnityEngine.Object.DestroyImmediate(wall);palette.Cancel();miracles.Suspended=false;miracles.tuning.unlimitedEnergy=unlimited;field.SetValue(slice,original);world.ResetWorld();for(int i=0;i<actors.Length;i++){actors[i].transform.SetPositionAndRotation(positions[i],rotations[i]);actors[i].GetComponent<IslandNavigator>().ResetRoute();}god.Interrupt("Provision QA complete");}
 }
}
}
